function cancelQuoting(context: TimelineRenderingType) {
    dis.dispatch({
        action: 'reply_to_event',
        event: null,
        context,
    });
}

interface IProps {
    permalinkCreator: RoomPermalinkCreator;
    replyToEvent: MatrixEvent;
}

